import 'package:flutter/material.dart';
import '../models/student.dart';

class StudentDialog extends StatefulWidget { final Student? student; final List<String> courses; const StudentDialog({super.key, this.student, required this.courses}); @override State<StudentDialog> createState() => _StudentDialogState(); }
class _StudentDialogState extends State<StudentDialog> { final form = GlobalKey<FormState>(); late TextEditingController name, roll, email, phone, date; late String course, status;
  @override void initState() { super.initState(); final s = widget.student; name=TextEditingController(text:s?.name ?? ''); roll=TextEditingController(text:s?.rollNo ?? ''); email=TextEditingController(text:s?.email ?? ''); phone=TextEditingController(text:s?.phone ?? ''); date=TextEditingController(text:s?.enrollmentDate ?? DateTime.now().toIso8601String().substring(0,10)); course=s?.course ?? widget.courses.first; status=s?.status ?? 'Active'; }
  @override Widget build(BuildContext context) => AlertDialog(title: Text(widget.student == null ? 'Add a student' : 'Edit student details'), content: SizedBox(width: 500, child: Form(key: form, child: SingleChildScrollView(child: Column(mainAxisSize: MainAxisSize.min, children: [_field(name,'Full name', (v) => v!.trim().length < 3 ? 'Enter the full name.' : null), _field(roll,'Roll number / ID', (v) => v!.isEmpty ? 'Roll number is required.' : null), _field(email,'Email address', (v) => !RegExp(r'^\S+@\S+\.\S+$').hasMatch(v!) ? 'Use a valid email.' : null), _field(phone,'Phone number', (v) => v!.trim().length < 8 ? 'Enter a valid phone.' : null), DropdownButtonFormField(value: course, decoration: const InputDecoration(labelText: 'Course / program'), items: widget.courses.map((x) => DropdownMenuItem(value:x, child:Text(x))).toList(), onChanged: (v) => setState(() => course=v!)), TextFormField(controller: date, decoration: const InputDecoration(labelText: 'Enrollment date', hintText: 'YYYY-MM-DD'), validator: (v) => DateTime.tryParse(v!) == null ? 'Use YYYY-MM-DD.' : null), DropdownButtonFormField(value: status, decoration: const InputDecoration(labelText: 'Status'), items: ['Active','Inactive'].map((x) => DropdownMenuItem(value:x, child:Text(x))).toList(), onChanged: (v) => setState(() => status=v!))])))), actions: [TextButton(onPressed: () => Navigator.pop(context), child: const Text('Cancel')), FilledButton(onPressed: submit, child: Text(widget.student == null ? 'Add student' : 'Save changes'))]);
  Widget _field(TextEditingController c, String label, String? Function(String?) validator) => TextFormField(controller:c, decoration: InputDecoration(labelText:label), validator:validator);
  void submit() { if (!form.currentState!.validate()) return; final s=widget.student; Navigator.pop(context, Student(id:s?.id ?? DateTime.now().microsecondsSinceEpoch.toString(), name:name.text.trim(), rollNo:roll.text.trim(), email:email.text.trim(), phone:phone.text.trim(), course:course, department:departmentFor(course), enrollmentDate:date.text.trim(), status:status)); }
}
